/// <summary>
/// Extension of button AVAInventSiteDelegateCancel for SalesTableListPage
/// </summary>
[ExtensionOf(formControlStr(SalesTableListPage, AVAInventSiteDelegateCancel))]
final class AVASalesTableListPage_DelegateCancelBtn_Extension
{
}

Method.Source:
/// <summary>
/// Extension of clicked method
/// </summary>
public void clicked()
{
    FormDataSource avaSalesTable_ds = element.salesTable_ds;
    SalesTable avaSalesTable = avaSalesTable_ds.cursor();

    avaSalesTable.avaUpdateDelegation(NoYes::No);

    avaSalesTable_ds.refresh();

    next clicked();
}
